INSERT INTO bygning (kommune_id,navn,bydel_navn,fagsystem_instans_id,ekstern_id,hjemmeside,epost,telefon,apningstid_tekst) SELECT k.id,'Bergen inkluderingssenter (BIS)','ÅRSTAD BYDEL',fi.id,'171','https://www.bergen.kommune.no/innbyggerhjelpen/bolig-og-sosiale-tjenester/inkludering/moteplasser/bergen-inkluderingssenter','bis@bergen.kommune.no','55 56 81 00','Ukedager: 08.00 - 21.00 Lørdag og søndag: 10.00 - 17.00 Juli: Ukedager: 08.00 - 16.00 Lørdag og søndag: stengt Weekdays: 08.00 - 21.00 Saturday and Sunday: 10.00 - 17.00 July: Weekdays 08.00 - 16.00 Saturday and Sunday: Closed Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid må du betale for utvidet vektertid. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. Dette må bestilles senest 14 dager før arrangementet. If you wish to rent or borrow the premises outside regular opening hours you must pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour. Booking has to be made at least 14 days in advance.' FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT DO NOTHING;
