INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'379',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Ny-Krohnborg fellesbibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='57'),NULL,NULL,'Ny-Krohnborg fellesbibliotek åpnet 25. august 2022, og er på kort tid blitt et pulserende samlingssted for befolkningen i bydelen. Det er både et inspirerende skolebibliotek for elevene på Ny-Krohnborg skole, og et inkluderende folkebibliotek som er åpent for alle fra kl.12. Her kan du låne og lese bøker på ulike språk, spille brettspill eller Nintendo Switch, studere og gjøre lekser, få språktrening og leksehjelp, eller delta på spennende arrangement og verksteder. Rommet er totalt ca. 80 kvm, har fast oppstilte bord og stoler, og brukes til ulike biblioteks aktiviteter som workshops, kreative verksteder, kurs og ulike møter. Rommet er utstyrt med projektor, lerret og lydanlegg. På dagtid disponeres denne utelukkende av Bergen offentlig bibliotek og Ny-Krohnborg skole. Ny-Krohnborg fellesbibliotek — Bergen Offentlige Bibliotek (bergenbibliotek.no) Arrangement på Ny-Krohnborg fellesbibliotek — Bergen Offentlige Bibliotek (bergenbibliotek.no)','Åpningstider Mandag: 12:00 - 16:00 Tirsdag: 12:00 - 19:00 Onsdag: 12:00 - 16:00 Torsdag: 12:00 - 19:00 Fredag: 12:00 - 16:00 Lørdag: Annenhver lørdag kl. 10:00 - 16:00 (partallsuker. 13. januar er første i 2024) Søndag: Stengt Bibliotekene — Bergen Offentlige Bibliotek (bergenbibliotek.no)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
