INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'110',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='7'),'Storsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Kultursal med piano og speilvegg. Stoler og bord tilgjengelig, kan rigges til 70 personer. Tilknyttet kjøkken med komfyr, dobbel kaffetrakter, mikrobølgeovn, vannkoker, oppvaskemaskin (steamer) og kjøleskap. Egnet til utstillinger, kurs/konferanser, selskaper, konfirmasjoner og lignende. Lerret og prosjektor tilgjengelig. For leievilkår, priser, etc, se "Nordnes bydelshus" (bygg/anlegg).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'140',k.id,NULL,'Øvingslokale',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Øvingslokale er åpent alle dager i uken. Mand-fred 17.00-23.00 lørd-sønd 11.00-23.00 Hver øvingsøkt er på 3 t. ( Kr 150.- ) Utstyr: Mikser, 4 kanaler stereo, 4 kanaler mono. Høytalere: 2xJBL Eon Aktive høytalere på stativ. Gitarforsterkere: 2xMarshall MG100DFX Combo, 1xVox AC50 med 4x12" kabinett. Bassforsterkere: 1x Ashdown EVO2 500w topp med 4x10" kabinett, 1x Peavey TKO115 combo. Slagverk med crash og diverse tammer.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'960',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='185'),'TEST Vielses-seremoni i Forhandlingssalen NB TEST',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='64'),NULL,NULL,'NB! ENN SÅ LENGE BARE TIL TEST - du kan ikke bestille tid her ENNÅ Bergen kommunes vigselsrom ligger i Magistratbygningen, også kalt Magistraten. Dette er en av de eldste administrasjonsbygningene i kommunen. Inngangspartiet og vigselsrommet er restaurert og tilpasset den høytidelige anledningen. Adresse Magistraten har adresse Rådstuplassen 5. Bygningen ligger mellom Bergen Rådhus og Bergen politistasjon. Inngangen vender mot Det gamle Rådhus. Møt opp 15 minutter før vielsen Brudepar og gjester møter opp 15 minutter før seremonien starter. Vigsler eller vigselsvert tar dere imot ved hovedinngangen til Magistraten. Seremonien varer i 15 minutter Vi setter av inntil 15 minutter per vigselsseremoni. Minst syv av disse minuttene går med til den formelle ekteskapsinngåelsen: lesing av vigselsformularet og signering av dokumenter. Innslag under vielsen Dere kan fylle den resterende tiden slik dere ønsker, for eksempel med egne innslag under seremonien eller fotografering. Husk at vielsen til sammen ikke kan vare lenger enn 15 minutter. Hvis dere ønsker egne innslag ber vi om at dere opplyser om det i søknaden. Dere er selv ansvarlige for å ta med alt dere trenger til eventuelle innslag . Vi har ikke utstyr som mikrofon, høyttaler, eller lignende. Fotografering og filming Det er mulig å ta bilder før og etter seremonien, både i trappen inne og utenfor ved hovedinngangen. Ta hensyn til andre brudepar som er til stede. Filming og fotografering er tillatt under hele seremonien. Gjester Til sammen er det plass til 25 personer inne i vigselsrommet. Det er 18 sitteplasser og to ståplasser, i tillegg til to stoler til vitnene/forloverne, to stoler til brudeparet og en stol til vigsler. HC-heis Gi beskjed til vigselsvert eller vigsler når dere kommer, hvis dere eller noen av gjestene deres har behov for HC-heis. Parkering Det er ikke mulig å parkere ved Magistraten, bortsett fra to offentlige HC-plasser. Nærmeste parkeringshus er ByGarasjen og GriegGarasjen. Det er mulig å slippe av og hente folk utenfor Magistraten. Feiring Vi oppfordrer til bruk av såpebobler utendørs, ikke konfetti eller ris, hvis dere feirer det ferske ekteparet.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
