INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'463',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='70'),'Øvingsbinge 13 (Økt)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Øvingsrommet er utstyrt med: 2 gitarforsterkere 1 bassforsterker 1 trommesett 1 Sang-PA Det koster kr 220 pr 3-timers økt i øvingslokalet. Bookingen registreres onsdager og fredager.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'670',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='142'),'Personalrom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='12'),NULL,NULL,'Personalrom',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'243',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='55'),'Bane 3',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Minihåndball og basketball.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'29',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='13'),'Sal 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Mot scene',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'106',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='10'),'Småsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Småsalen er ca 90 m2 og brukes til flere formål: utstillinger, konserter, dans, mindre forestillinger, foredrag/seminarer, møter, mm. Leietakere har ansvar for å vise hensyn til utstillinger i rommet slik at verkene ikke kommer til skade. Rommet inneholder prosjektor, lerret, billedlys, lystette gardiner, flygel og lyd- og lys anlegg. Store vinduer langs ene veggen med godt dagslys og utsyn til elven. Utgang til luftebalkong fra foajèen. Det er mulighet for å sette opp bord og stoler etter behov. Praktisk informasjon ved utleie av kulturlokalene Kulturlokalene er først og fremst beregnet til kulturaktivitet men leies også ut til konferanser, seminarer, møter etc. (leies ikke ut til private formål) Bemanning: Kulturhuset er betjent med en "kjentmann" i ukedagene, men huset er ubetjent lørdag og søndag. Leietakere er ansvarlig for vakthold ved eget arrangement og vi gjør oppmerksom på at det er krav om minimumsbemanning ( se eget dokument for mer informasjon) Kulturkontoret kan være behjelpelig med å skaffe frivillig bemanning til Kr. 150,- pr time. (søknadsfrist) Huset er et flerbrukshus, det betyr at det forgår paralelle arrangement og leietakere må ta hensyn til hverandre. Renhold utføres en gang pr dag, mandag til og med fredag. Det blir ikke utført renhold lørdag og søndag med mindre dette avtales på forhånd. Opprydding, leietakere er ansvarlig for opprydding etter arrangement. HMS, se dokumenter knyttet til søknad. Priser: Lag/organisasjoner: Gratis! Andre leietakere: Kr 1500,- halv dag (inntil 4 timer) Kr 3000,- hel dag (inntil 8 timer) I tilfeller der leietaker har en samarbeidsavtale med Fana og Ytrebygda Kulturkontor gjelder vilkårene oppgitt i avtalen. Kommersielle aktører: Pris etter avtale',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'289',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='11'),'Sal 2 nye hall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Basketball og mini håndball',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'125',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='10'),'Kultursalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Kultursalen er beregnet for større konserter, forestillinger og seminarer. Sitteplasser: 359 i amfiet med mulighet for å sette inn inntil 41 ekstra stoler foran. Ståplasser: 600 Det er en moderne sal med god akkustikk og profesjonelt utstyr. Den har blitt omtalt som Bergens nye storstue og kan sammenlignes med Per Gynt salen i Grieghallen. Kultursalen har huset flere nasjonale artister og har fått et godt renomè som scene. Kultursalen gir også amatører, lag og organisasjoner mulighet til å opptre på en profesjonell arena. Det er stor sceneinngang hvor utstyr kan tas inn direkte på scenen. Det kan følge med 30 sceneelementer 2x1m, med 3 ulike benhøyder ved leie. 2 artistgarderober er tilknyttet til salen. Elektrisk sceneteppe foran, samt 2 manuelt styrte baktepper, i tillegg til flanketepper på hver side. Størrelse på scenen er 11 meter dyp x 14,5 meter bred, høyde ca. 7 meter til rigg. Praktisk informasjon ved utleie av kulturlokalene Kulturlokalene er først og fremst beregnet til kulturaktivitet men leies også ut til konferanser, seminarer, møter etc. (leies ikke ut til private markeringer) Bemanning: Kulturhuset er betjent med en "kjentmann" i ukedagene, men huset er ubetjent lørdag og søndag. Leietakere er ansvarlig for vakthold ved eget arrangement og vi gjør oppmerksom på at det er krav om minimumsbemanning ( se eget dokument for mer informasjon) Kulturkontoret kan være behjelpelig med å skaffe frivillig bemanning til Kr. 150,- pr time. (søknadsfrist) Huset er et flerbrukshus, det betyr at det forgår paralelle arrangement og leietakere må ta hensyn til hverandre. Det betyr at alle må holde seg til det utleieobjektet som er bestilt og at utstyr ikke må flyttes fra et utleieobjekt til et annet uten at dette er avtalt på forhånd Renhold utføres en gang pr dag, mandag til og med fredag. Det blir ikke utført renhold lørdag og søndag med mindre dette avtales på forhånd. Opprydding, leietakere er ansvarlig for opprydding etter arrangement. Leiepriser: Eksterne leietakere: Kr. 5.000,- for halv dag (inntil 4 timer) Kr. 10.000,- for hel dag (inntil 8 timer) Lag/organisasjoner: Gratis! Kommersielle aktører: Pris etter avtale I tilfeller hvor det foreligger en samarbeidsavtale mellom leietaker og Fana/Ytrebygda Kulturkontor gjelder vilkårene som er definert i avtalen. Ved avbestilling av kultursalen: Se leieavtale Diverse: Lyd/lystekniker: Leietaker må benytte eksterne teknikere etter avtale med saksbehandler. Vakthold: Etter avtale HMS, se dokumenter knyttet til søknad.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'700',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='140'),'Rom 15 klasserom buebygg',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Rom 15 klasserom i buebygget tilsvarer rom 185 i branntegning Klasserom med plass til 20. Passer til møter/kurs',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'590',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='10'),'Utstilling',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='21'),NULL,NULL,'Småsalen i Fana kulturhus brukes som visningsrom, men også til flere andre formål, som konserter, dans, mindre forestillinger, foredrag/seminarer, møter, mm. Utstiller kan søke om utstillingsperiode etter avtale med Fana og Ytrebygda kulturkontor. Kontakt tormod.kayser@bergen.kommune.no for avtale om utstillingperiode. Opplysninger om utstillingslokalet: Alle vegger er hvitemalte. Mål: Gulvareal er ca 90 kvadratmeter. Kort vegg (ved inngangsdør) 1.27m + dør + 1.51m Lang vegg : 9.55m Endevegg : 7.58m Vindu langs hele ytterveggen. Se bilder Opphengning: List langs taklist med vaiere og kroker. Bildene må ikke veie for mye. Det kan ikke settes skruer i veggene. Utstilleren er selv ansvarlig for frakt, montering og salg av utstillingen. Kulturhuset kan være behjelpelig med montering på dagtid etter avtale. Forsikring: Utstiller er selv ansvarlig for arbeidene i utstillingsperioden. Dette gjelder både skade/tap og tyveri. Utstiller må selv sørge for å forsikre bilder/gjenstander som stilles ut i Fana kulturhus dersom dette ansees som nødvendig. Henting av arbeider: Hvis arbeidene ikke hentes innen 4 uker etter utstillingsperioden, blir de sendt tilbake på utstillers regning.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'810',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='161'),'Svømmebasseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='15'),NULL,NULL,'Spesialbasseng 12,5 x 8m',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'65',k.id,NULL,'Klubben',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Klubben er et fleksibelt rom som passer for mange ulike aktiviteter. De ter greit med plass til ca 40 personer og lokalet egner seg spesielt godt som klubblokale, møte- og kurslokale, og til mindre sammenkomster som barnedåp og konfirmasjoner. Ved større arrangementer brukes Klubben gjerne sammen med Helan, da som kafélokale. Klubben har fastmontert projektor med automatisk lerret, CD-/DVD-spiller, samt et enkelt lydanlegg. Lite kjøkken med kaffetrakter, komfyr, kjøleskap og oppvaskmaskin. Lokalet har 45 stoler og 10 bord. Leietaker har selv ansvar for å vaske og rydde på plass utstyr som er brukt. Av hensyn til Åsane fritidsklubb som har sine faste aktiviteter i lokalet må inventar settes på plass som anvist på oppslag.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'96',k.id,NULL,'Veten',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Møterom med sitteplass til 12 personer. Godt dagslys via takvindu. Lokalet har ikke projektor eller lerret tilgjengelig, og dersom det er behov for slikt utstyr må leietaker medbringe dette selv. Lokalet eies av Åsane Storsenter, men forvaltes av Arna og Åsane kulturkontor. Åsane Storsenters leietakere kan leie lokalet gratis, men det må likevel bookes på forhånd. For øvrige leietakere, se prisliste i leiebetingelsene for Åsane kultursenter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'33',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='13'),'Sal 4',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Sal nr 4 fra scene.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
