INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'50',k.id,NULL,'Speilsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Speilsalen er en dansesal med dansegulv, barer og speilvegg. Salen passer passer godt for både dans, yoga, trim og lignende aktiviteter. Det er CD-spiller tilgjengelig, og mulighet for å koble til musikk fra PC, smarttelefon eller lignende via kabel til lydanlegget. I tilknytning til Speilsalen er det to garderober tilgjengelig. Speilsalen ligger i 3. etasje, opp trappen fra inngangen til kultursenteret.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
