INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'435',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN Bandrom 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='16'),NULL,NULL,'LINKEN Bandrom 2 Utstyr i Bandrom 2: Mikser, mikrofoner og pa system, trommesett, bassforsterker, to gitarforsterkere, el-piano. Bandrom 2 er tilsluttet Lydstudioet og kan brukes som innspillingsrom. Pris: -Ungdom til og med 25 år: : kr. 50/time -Frivillige/ideelle organisasjoner: kr. 50/time. -Voksne kr. 150/time. -Kommersielle aktører kr. 150/time. Aktivitetskortet fra Bergen Kommune kan benyttes for å dekke øvingsleien. Påberegnes inntil 3 dagers behandlingstid på søknader.','10:00 - 22:00 alle dager',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
