INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'747',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'Tilgjengelig for booking: Ukedag Fra Til Mandag 08:30:00 22:00:00 Tirsdag 08:30:00 22:00:00 Onsdag 08:30:00 22:00:00 Torsdag 08:30:00 22:00:00 Fredag 08:30:00 22:00:00 Lørdag 09:30:00 22:00:00 Søndag 09:30:00 22:00:00 Dansesalen er en sal med dansegulv, barer og speilvegg. Gulvarealet er 84,5 m2. Salen passer passer godt for både dans, yoga, trim og lignende aktiviteter. Det er musikkanlegg tilgjengelig, samt mulighet for å vise dans på skjerm. I tilknytning til dansesalen er det to garderober (3 og 4) med låsbare skap. Speilsalen ligger i 2. etasje, opp trappen ved biblioteket. På grunn av spesialgulv må det ikke brukes sko med harde såler eller sko som setter merker i gulvet. Det er ikke tillat med mat og drikke i Dansesal.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
