INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'959',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='34'),'Møterom 2. etg',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Tilgjengelig for lån til lag og organisasjoner o.l. i nærmiljøet. Møterommet er ved kafeteriaen, og er innredet med møtebord og stoler med plass til ca 10-12 personer. Møterommet har stor skjerm til låns. Trådløst internett (bk-gjest). Det er mulig å bruke kjøkken i kafeen for å koke kaffe og tevann. Rommet bookes i totimers-bolker, med maks to ganger pr dag. Nøkkelbrikke må hentes hos personalet i hallen på dagtid.','Hverdager mellom kl 16.00 - 21.00 Lørdag og søndager: kl 12.00 - 19.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'968',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='44'),'Vadmyrahallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'733',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='158'),'Kanoer (8stk) m/tilhenger',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Etat for idrett har 8 kanoer, padleårer og vester til utlån for skoleklasser, lag, organisasjoner med flere. Ønsker du å låne kanoene sender du søknad via Aktiv kommune til Etat for idrett (kalender nedenfor). Lån av kanoene er gratis. Søknad kan bli avslått dersom utlån/innleveringstidspunkt faller utenfor Etat for idrett sine åpningstider mandag til fredag kl. 08.00 - 15.00. Regler for bruk av kano: Bruk av redningsvest/flytevest er påbudt. Personer som ikke er svømmedyktige må bruke redningsvest. Låntaker er ansvarlig for bruk av kanoene/kajakkene og skal alltid ha oppsyn med bruken. Ansvarlig må være fylt 18 år og kunne grunnleggende førstehjelp. Kanoene/kajakkene tømmes for vann etter bruk. Vestene tørkes før innlevering. Mangler ved lånt utstyr skal innrapporteres. Kanoer Vi har til utlån 8 kanoer av typen Hasle. Kanoen har plass til 3 personer. Vi har flytevester i følgende vektkategorier: 30-40 kg 40-50 kg 50-60 kg 60-70 kg 70-90 kg 90 kg +','Utlevering mandag til fredag kl. 08.00 - 15.00.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'644',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='134'),'Øvingsrom 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='16'),NULL,NULL,'Øvingsrom 1 (Rom 005) er utstyrt med: Forsterkere til bassgitar og el-gitar Trommesett Rommet egner seg til mindre grupper (1-3 personer) Størrelse: 11m²',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'744',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Utstillingslokale',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='21'),NULL,NULL,'Godt belyst lokale på ca. 70 kvadratmeter, med omtrent 30 meter disponibel vegglengde totalt. Rommet er 13 meter dypt og 4,85 meter bredt. Lokalet har gjennomgang til biblioteket og ligger i utsiktssonen fra Servicesenteret, noe som gir trafikk og synlighet. Rommet utgjør en egen alarmsone med kameraovervåking fra utsiden. Det er stikkkontakter i golvbrønner, og muligheter for å skru fast ting i veggene. Vilkår for utleie av Utstillingslokale: Forvaltning av utstillingsrommet er beskrevet i driftsmodellen for Åsane kulturhus, vedtatt av Bystyret i Bergen den 23.10.19. Disse vilkårene utfyller bestemmelsen i driftsmodellen. I driftsmodellen heter det på generelt nivå: «Det er et uttalt mål at kulturhusene skal være mest mulig tilgjengelige for alle og at frivillige kulturaktører skal ha gode rammevilkår. For å likestille alle frivillige organisasjoner, er det byrådets ønske at frivillige organisasjoner innenfor kulturfeltet skal få benytte kommunale kulturbygg uten krav om betaling av husleie. Utover å legge til rette for den lokale amatørkulturen på en best mulig måte, er det også viktig å gi gode rammevilkår for profesjonelle kulturaktører som har tilhørighet til kulturbygget. Gjennom dynamisk prissetting der tilpassede prisavtaler inngås med de ulike aktørene, vil man kunne bidra til at semiprofesjonelle og profesjonelle aktører tør å satse på prosjekter i samarbeid med lokale aktører. Disse arrangementene vil kunne være med på å nå ut til en større brukergruppe, og gjerne tiltrekke seg nytt og større publikum som vil oppleve dette som en relevant kulturarena og vil ønske å komme tilbake.» Helt konkret for utstillingsrommet står følgende: «Når det gjelder utstillingsrommet vil det etableres en kommisjonsordning av kunstsalg heller enn husleie. En kommisjon på 30% vil ligge på samme nivå som kunstforeninger benytter. Det må vurderes om personer eller grupper som er nyutdannede/nyetablerte profesjonelle bør bli behandlet som en egen kategori, for å sikre nyskaping og variasjon i kulturtilbudet. Eventuelt kan en kommisjonsordning også være aktuell her.» Disse prinsippene bygger på saken om fri leie for kulturorganisasjoner; Retningslinjer og kriterier for tilskuddsordninger innen kunst- og kulturområdet, vedtatt 19.12.17. Visningsrommet lånes ut gjennom kommunens bookingsystem Aktiv kommune. Søknad om utstilling må være sendt inn i og innvilget av saksbehandler i Aktiv kommune for at den skal være gyldig. I utgangspunktet er ikke Åsane kulturhus gallerist eller arrangør for utstillinger i utstillingsrommet, men leier eller låner rommet ut til enkeltpersoner, grupper eller organisasjoner som selv arrangerer utstillinger. I markedsførings-sammenheng kan Arna og Åsane kulturkontor/Åsane kulturhus være en samarbeidspart, men er fortsatt ikke arrangør. I henhold til bystyresaken skiller vi derfor mellom 4 typer leietakere: Profesjonelle kunstnere må betale 30% av salget som kommisjon for å få benytte lokalene. Nyutdannede profesjonelle kunstnere (definisjon: som har avsluttet sin utdanning på Bachelor eller mastergradsnivå i løpet av de siste tre årene), samt andre enkeltpersoner som stiller ut verker for salg, betaler en ukeleie for lokalet. 1. uke koster kr 2 000,- og påfølgende uker kr 1 000 pr. uke. Frivillige organisasjoner eller f. eks. ateliergrupper får fri leie. Praktisk informasjon om bruk av Utstillingslokale : Du kan bruke mellomstore spiker eller oppheng i nylon (fisketråd) festet i taklisten for å henge opp dine bilder. Vi har fisketråd på lager, så spør aktivitetsverten om dere ønsker dette. Det er ikke lov å bruke store spiker, skruer eller gipsplugger i veggen. Det er heller ikke lov til å bruke lim/tosidig teip og lignende. Når spikere skal trekkes ut ved endt utstilling, bruk et mellomlag, for eksempel en planke, for å unngå lage merker på veggen. Justér gjerne på lampene i taket for at de skal fremheve din kunst. Spør i tilfelle aktivitetsvert om å få låne stige. Hvis du har andre spørsmål, ta kontakt med aktivitetsverten. Feil bruk av Utstillingslokale kan medføre erstatningsansvar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'967',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='42'),'Mathopen idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'764',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Grupperom Voksenopplæring (Rom 3114) (UKEDAGER FRA KL. 16.00)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Grupperom på ca. 12 m2, møblert med bord og stoler, men akustisk tilrettelagt for musikk. Egner seg som øvingsrom for enkeltøving eller grupper på inntil 4 personer. Tilgjengelig for booking: Mandag 16:00:00 22:00:00 Tirsdag 16:00:00 22:00:00 Onsdag 16:00:00 22:00:00 Torsdag 16:00:00 22:00:00 Fredag 16:00:00 22:00:00 Lørdag 10:00:00 22:00:00 Søndag 10:00:00 22:00:00',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'969',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Kantineområdet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,NULL,'Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'868',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Gymsal 1 - Kampsport',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Gymsal tilrettelagt for kampsport, Boksesekker Liten klatrevegg','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays : 08.00-21.00 Saturday and Sunday : 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'450',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Kulturverksted 1 og 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='57'),NULL,NULL,'Kulturverksted 1 og 2 er ett rom som ved behov kan deles i to med en skillevegg. Rommet er totalt ca. 40 kvm, har fast oppstilte bord og 24 stoler, og brukes til ulike workshops, kreative verksteder, kurs og ulike møter. Rommet er utstyrt med prosjektør og lerret. Kulturverksted 2 er nå brukt som ungdomsrom. Rommet er utstyrt med PS4 og tv. Perfekt rom for ungdommer for å henge.','Mandag- fredag kl.08-22.30 Lørdag og søndag kl.09-21.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'928',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Bibliotek/Folkotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='57'),NULL,NULL,'Folkoteket er utstyrt med: Liten scene Prosjektor med lerret Lydanlegg Mikrofoner og mygg Lite kjøkken 2 langbord med plass til 20 sitteplasser 6 runde bord med plass til 24 personer Mulighet for å sette inn flere stoler og bord God akustikk Piano 5 tilhørende grupperom Salen egner seg til konserter, små forestillinger, seminarer og andre arrangement. Brukes også som øvingslokale for kor og orkester. Det er mulig å ommøblere rommet og sette inn ekstra stoler og bord Leietakere er ansvarlig for opprydding etter arrangement. Rommet leies ikke ut til private arrangementer. Tilhørende mesanin/galleri med flere sitteplasser Størrelse: Folkotektet 379m2 Størrelse: Mesanin/galleri 108m2 Fra 2027 flytter Landås bibliotek inn og lokalet blir ikke tilgjengelig for utlån.','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'857',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='166'),'Gamle gymsal - lørdag og søndag for barn og elever i skolekretsen 10-18',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Kronstad oppveksttun låner ut gamle gymsal til elever og barn i skolekretsen. Bruken skal være knyttet mot barnebursdager, for at alle på trinnet blir inkludert. Husk å oppgi ditt mobilnummer i søknaden. Utleie omfatter ikke lån av utstyr som tilhører Norrøna Turn. I henhold til instruks for brann-rutiner skal røykmaskin IKKE brukes.','Mandag - torsdag har idrettsrådet i Bergen tildelt treningstider til idrettslagene. Fredag er tildelt FAU Lørdag og søndag utleie fra 10.00 - 18.00. Utleie følger skoleruten med høstferie, vinterferie, juleferie og påskeferie. Grunnet egne arrangementer avsluttes leieforholdet 14. juni 2026.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'378',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Kultursal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Kultursalen er utformet som en black box sal med teleskopamfi (115 seter), lyd- og lysanlegg, prosjektor/lerret og piano. Det finnes også et lite backstageområde med tekjøkken, garderobe med sminkespeil, dusj og wc. Salen leies ut først og fremst til kulturaktivitet i regi av frivillige lag/organisasjoner, f.eks kor, korps, dansegrupper, teatergrupper etc. Barn og unge er prioritert målgruppe. Det er også mulig å leie salen til møter, kurs og konferanser. Rommet leies ikke ut til privatarrangementer. Alle arrangement må være alkoholfrie/rusfrie. For leievilkår, prisliste, etc, se "Ny-Krohnborg senter" (bygg/anlegg). Kultursalen er utformet som en black box sal med teleskopamfi (115 seter), lyd- og lysanlegg, prosjektor/lerret og piano. Det finnes også et lite backstageområde med tekjøkken, garderobe med sminkespeil, dusj og wc. Salen leies ut først og fremst til kulturaktivitet i regi av frivillige lag/organisasjoner, f.eks kor, korps, dansegrupper, teatergrupper etc. Barn og unge er prioritert målgruppe. Det er også mulig å leie salen til møter, kurs og konferanser. Rommet leies ikke ut til privatarrangementer. Alle arrangement må være alkoholfrie/rusfrie. For leievilkår, prisliste, etc, se "Ny-Krohnborg senter" (bygg/anlegg). Har du spørsmål? Ta kontakt med senterkoordinator Dennis Osei Kontor, som har kontor på Ny-Krohnborg senter. E-post: dennis.oseikontor @bergen.kommune.no . Tlf: 53 03 31 88 / 40802516. Ring etter kl 13.00.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
