INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'832',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='136'),'Kjøkken og kantine',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='5'),NULL,NULL,'Kjøkkenet og kantine leies ut felles. Egner seg til matkurs, styremøter o.l.','Leies ut fra kl17.00 til 21.00 i ukedager. Vi leier også ut i helger.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'1028',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='125'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'424',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Kantine',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Dette er Ny-Krohnborg oppveksten sin kantine arealet. På dagtid disponeres denne utelukkende av skolen. På ettermiddag/kveld brukes den til møter og samlinger, hovedsaklig i tilknytning til oppveksttunet. Kantinen arealet kan i noen tilfeller leies ut til frivillige lag og organisasjoner, og private arrangementer etter skoletiden under særskilte vilkår. F or eksempel dåp, navnedag, konfirmasjon, bryllup, runde dager, osv. Rommet er utstyret med 75-tomme tv, og lydanlegg som kan settes opp ved behov. Bord og stoler må sette på plass etter bruk, ser digital omvising. Kantine-kjøkkenet er ikke med i denne bestillingen/ ressurs. For generelle leievilkår, prisliste, etc., se "Ny-Krohnborg senter" (bygg/anlegg).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'926',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Musikk/dramarom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'Musikk/drama-rommet er utstyrt med: Piano Miksepult Mikrofon Lydanlegg via blåtann Speil Spesial gulv til dans i3touch skjerm - i3touch er en stor, interaktiv skjerm som fungerer som ei digital tavle. Du kan skrive, tegne og styre innhold direkte på skjermen med fingeren eller en penn Innebygde høgtalere, USB-C-tilkopling Rommet brukes daglig som ordinært klasserom. Stoler og pulter må ryddes bort og settes tilbake etter bruk. Det finnes også en miksepult og et piano tilgjengelig i rommet, og det er viktig at dette utstyret ikke skades. Rommet er godt egnet til aktiviteter som korøving, dans og yoga. Rommet skal ikke brukes til barnebursdager. Dessverre ingen mulighet for lagring Størrelse: 102m2','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
