INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'919',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Gymsal 3 - Dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Denne idrettssalen har speil og er utstyrt med: Mikrofon Lydanlegg med blåtann Innebygde høyttalere med USB-C-tilkobling Speil Bordtennisbord Turnmatter Nedsprangsmatte (tjukkas) Hva slags aktiviteter passer i salen? Salen brukes til idrettsaktiviteter som ikke skader speil et på veggen . Ballsport er derfor ikke tillatt. Eksempler på passende aktiviteter: Dans Bordtennis Styrketrening Aerobic og Yoga Andre «rolige» aktiviteter Mandag til fredag (ettermiddag og kveld): Salen brukes av idrettslag med faste treningstider. Lørdag og søndag: Grupper på opptil 20 personer kan reservere salen. Du kan reservere inntil 2 timer per dag. Tilgjengelig utstyr i helgen: Vegg med speil Bordtennisbord og racketer Turnmatter Yogamatter Hoppemadrass Badmintonracketer (merk: det finnes ikke stativ til badminton) Du kan ta med eget småutstyr hvis du trenger det til din aktivitet. Lagring av utstyr: Bare idrettslag med faste treningstider kan lagre utstyr, og det må avtales med Etat for idrett.','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays : 08.00-21.00 Saturday and Sunday : 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'434',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN Bandrom 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='16'),NULL,NULL,'LINKEN Bandrom 1 Utstyr i Bandrom 1: Mikser, mikrofoner og pa system, trommesett, bassforsterker, to gitarforsterkere, el-piano og orgel. Bandrom 1 er tilsluttet Lydstudioet og brukes ofte som innspillingsrom. Pris: -Ungdom til og med 25 år: : kr. 50/time -Frivillige/ideelle organisasjoner: kr. 50/time. -Voksne kr. 150/time. -Kommersielle aktører kr. 150/time. Aktivitetskortet fra Bergen Kommune kan benyttes for å dekke øvingsleien. Påberegnes inntil 3 dagers behandlingstid på søknader.','10:00 - 22:00 alle dager',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'921',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='181'),'Venterommet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),40,'kilde','Venterommet er utstyrt med: 4 større bord med benker og stoler Tilsammen 20 stoler Sittegruppe med 2 sofaer, stol og bord Speilvegg (kan dekkes til) Projektor (mobil) PA-anlegg Kjøkkenkrok (til enkel bevertning) TV med tilkobling/HMDI-kabel Størrelsen på lokalet er ca. 180 kvm. Kapasitet 40 personer. Dersom det er behov for ekstra stoler kan det ordnes. Det er per. i dag ikke tillatt å tilberede mat i lokalet, eller spille forsterket musikk, med hensyn til nabolokalet. Frivillige lag og organisasjoner som er registrert i Frivillighetsregisteret kan ha rett på gratis leie av Venterommet. Leiepriser for Venterommet: Inntil 4 timer: kr 1000,- Hel dag: kr 3000,- Helg (lørdag): kr 4000,-','Mandag-fredag: kl. 08.00-22.00 Lørdag: kl. 08.00-20.00 Søndag: STENGT',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'935',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Klasserom 217',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Klasserom 217 er utstyrt med: 18 pulter med stoler i3touch skjerm - i3TOUCH er en stor, interaktiv skjerm som fungerer som ei digital tavle. Du kan skrive, tegne og styre innhold direkte på skjermen med fingeren eller en penn. Innebygde høgtalere, USB-C-tilkopling Dessverre ingen mulighet for lagring Størrelse: 40m2','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'123',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='10'),'Møterom - Hamrefjellet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Møterom med plass til 14 personer. 15m2. Kun bord og stoler. Tilgang på ambulerende prosjektor etter avtale med utleier. Inngang via hovedinngangen, deretter heis eller trapp til plan 2. Priser: Lag/org med kulurrelatert aktivitet gratis i ukedagene Andre Kr. 300,- pr time Praktisk informasjon ved utleie av kulturlokalene Kulturlokalene er først og fremst beregnet til kulturaktivitet for barn og unge Kulturhusene er ubetjente, dette medfører at leietakere må rigge og rydde selv Lokalene (ressursene) brukes av flere organisasjoner daglig, vi gjør oppmerksom på at renhold utføres en gang pr dag, mandag til og med fredag. Det blir ikke utført renhold lørdag og søndag Ta med utskrift av innvilget søknad ved utlevering av nøkkelkort hos Fana og Ytrebygda kulturkontor, Østre Nesttunvei 18 Leietaker er ansvarlig for at dører holdes lås under arrangement eller at det er vakt i døren',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'742',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Kultursal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Kultursalen er beregnet for større konserter, forestillinger og seminarer. Scenestørrelse: Ca. 200m2. Publikumskapasitet: Sitteplasser: 485 i amfiet. Det er mulig å sette inn inntil 15 ekstra stoler foran amfiet. Ståplasser: 910, dersom amfiet er parkert. Dette inkluderer 102 sitte-plasser på balkong. Dette er en moderne sal med god justerbar akustikk (EAS) og profesjonelt utstyr. Det er stor sceneinngang hvor utstyr kan tas inn direkte på scenen. Garderobe 1 og Garderobe 2 ligger i umiddelbar nærhet og kan leies sammen med salen, og et felles backstage-område kan benyttes. Krav til bruk av teknisk utstyr i Kultursal: • For å bruke salens utstyr stilles det krav til at arrangør har med erfarne lyd-, lys- og sceneteknikere/systemteknikere. Alternativt kan kulturkontoret være behjelpelig med å skaffe teknikere via våre kontakter - kontakt teknisk ansvarlig Sveinung Myrjord, e-post: sveinung.myrjord@bergen.kommune.no • Det skal ikke gjøres endringer i teknisk oppsett uten at det er avtalt med husets systemtekniker.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'987',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='187'),'Ressurs i annan instans - test',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='2'),NULL,NULL,'Test: Du må trykke på lenke lenger ned for å booke tid i "Hall X": Du vil forlate "Fylkeinstansen" - og bytter til "kommuneinstans". Søknad om brukstid for "Hall X" vil sendast til aktuell kommune - og bli saksbehandla der. (Eigne vilkår må lesast og aksepterast) https://oygarden.aktiv-kommune.no/bookingfrontend/client/no/resource/338 eller Booking av Hall X (Rong - testbygg Øygarden)',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'991',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='42'),'Aktivitetssal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,NULL,NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'990',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='148'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,NULL,NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'989',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='191'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'698',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='140'),'Base 13/14 i buebygg (178-180)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Base 13/14 base i buebygget tilsvarer baserom 178-180 i branntegning. Stor base med plass til 40. Passer til møter/kurs',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'697',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='140'),'Musikkrom (171 / 174)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,'Musikkrommet blir ofte leid ut til bursdagsfeiringer. Et stort fint lokaler med glade farger, speilvegg og tilgang til bord og stoler. Rommet ligger ved siden av Mat&Helse, som ofte blir leid ut sammen med dette, der du kan tilberede enkel matlaging, for eksempel. varme pølser, steke pizza o.l Bord og stoler er tilgjengelig i garderoben.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'830',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='34'),'Grupper - barnehage/skole',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='9'),NULL,NULL,'Trykk deg inn på ønsket tidsperiode i kalenderen og registrer med lærer/leders mobilnummer samt antall elever. Ansvarlig person som har meldt på må være med når gruppen møter opp i Bergenshallen. Tidene ligger i faste bolker, men man kan dukke opp etter starttidspunktet. Totalt antall mennesker på isen er 150. Dette for at man skal få en god opplevelse og ikke gå i kø hele tiden.','Mandag, torsdag og fredag kl 1000-1200 Tirsdag og onsdag kl 1000-1400',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'699',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='140'),'Gymsal (151)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Gymsal rom 151 Gymsal blir som oftest leid ut til idrettslag eller private som bruker salen til trening.Den er gjerne fullbukket av aktiviteter som går fast gjennom hele skoleåret.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'961',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='29'),'Dansesal 1 (stor)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Dansesalen har parkett, musikkanlegg og speilvegg. Gulvarealet er 60 m2. Salen passer godt for både dans, yoga, trim og lignende aktiviteter. Det er musikkanlegg tilgjengelig med blåtann oppkobling. Vi har ikke garderobe kun et større handicap toalett i foaje som kan brukes for omkledning. Speilsalen ligger i 1.etg inn en sort dør på høyre side i enden av gangen. Ta kontakt med personalet på Fysak for lån av nøkkel til dansesal. Salen må låses og nøkkel leveres tilbake. På grunn av spesialgulv må det ikke brukes sko med harde såler eller sko som setter merker i gulvet. Det er ikke tillat med mat og drikke i Dansesal.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'962',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='29'),'Dansesal 2 (mindre)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Dansesalen er en sal med dansegulv, musikkanlegg og 2 speilvegger. Gulvarealet er 45 m2. Salen passer godt for både dans, yoga, trim og lignende aktiviteter. Det er musikkanlegg tilgjengelig med blåtann oppkobling. Vi har ikke garderobe kun et større handicap toalett i foaje som kan brukes for omkledning. Speilsalen ligger i 1.etg inn nest siste sorte dør på høyre side i enden av gangen. Ta kontakt med personalet på Fysak for lån av nøkkel til dansesal. Salen må låses og nøkkel leveres tilbake. På grunn av spesialgulv må det ikke brukes sko med harde såler eller sko som setter merker i gulvet. Det er ikke tillat med mat og drikke i Dansesal.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'437',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN Studio',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='17'),NULL,NULL,'LINKEN Studio Imac Behringer X-32, digitalmikser/lydkort 16 mikrofoninnganger Mikrofoner til vokal og instrumenter Genelec monitorer ProTools(ikke lisens) Cubase 5 + 10 Pro Ableton live Reason 5 FL Studio Lydstudio er knyttet til Bandrom 1 og 2 via multikabler, og der er vindu mellom studio og bandrom 1. OBS: Dersom man ønsker å benytte bandrom til innspilling må disse bookes samtidig, da det ikke følger med automatisk. Pris: -Ungdom til og med 25 år: gratis -Frivillige/ideelle organisasjoner: kr. 50/time. -Voksne kr. 150/time. -Kommersielle aktører kr. 150/time. Aktivitetskortet fra Bergen Kommune kan benyttes for å dekke leien. Påberegnes inntil 3 dagers behandlingstid på søknader.','10:00 - 22:00 alle dager',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'828',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='165'),'EGGET',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='13'),NULL,NULL,'Informasjon om Egget Egget er et gratis overnattingstilbud til barnefamilier i Bergen kommune. Minst ett av barna må være under 12 år. Du finner hytten i Krohnegården friluftsområde i Fyllingsdalen. Det er kort vei fra nærmeste kollektivholdepass og parkeringsplass. Det er benk og bålplass i nærheten av Egget, og ved Storavatnet er det et fint utkikkspunkt og en sosial samlingsplass. Egget ligger få minutters gange fra Krohnegården badeplass, hvor det er tilrettelagt med toalettfasiliteter. Hytten er enkelt utstyrt og har plass til en liten barnefamilie. Det er plass til at to voksne og to barn kan overnatte. I Egget er det en vedovn og vindu med utsikt til Storavatnet og nærområdet. Egen medbrakt ved må benyttes til oppvarming av hytten. Nyttig informasjon Det er plass til at fire personer kan overnatte i Egget (to voksne og to barn). Hytten er 11 kvadratmeter. Egget har ikke innlagt strøm og vann. Ta med varme klær om vinteren og på kalde dager, og ved til oppvarming i ovnen. Ta også med mat, drikke, sovepose, liggeunderlag, innesko/ullsokker og lommelykt/hodelykt. All matlaging skal foregå ute. Det er tilrettelagt for grilling ved Krohnegården badeplass like i nærheten. I friluftsområdet finnes det toalettfasiliteter (friluftstoalett/utedo uten vann), som kan benyttes. Toalettet skal holdes rent og ryddig. Husk å ta med toalettpapir. Regler for lån av Egget Leietaker (den som søker) er ansvarlig for bruk av hytten. Nøkkel til hytten hentes hos Innbyggerservice i Kaigaten 4. Nøkkel må hentes og leveres innenfor kontorets åpningstid, mandag-fredag mellom kl 08:00 og 15:00. Nøkkel hentes tidligst dagen før du skal låne hytten, og leveres tilbake samme sted første virkedag etter lån av hytten. Innbyggerservice har stengt helger/helligdager. Skal hytten leies lørdag eller søndag må nøkkel hentes senest klokken 15:00 på fredag. Får vi ikke nøkkelen i retur blir leietaker fakturert. Det vil bli krevd legitimasjon for å hente nøkkel, og den som henter er ansvarlig for at den blir levert tilbake. Innsjekk er tidligst kl.15:00 og utsjekk er innen kl.12:00. Om du ikke kan benytte hytten, må du gi beskjed, slik at andre kan låne hytten. For avbestilling benytter du link i booking-bekreftelsen din. Avbestilling må skje minimum 24 timer før innsjekk. All bruk av åpen ild ut over bruk av vedovn er strengt forbudt i hytten. Dette gjelder også stearinlys. Det er ikke tillatt med bålbrenning i området rundt hytten. Bålbrenning skal foregå ved tilrettelagt bålplass ved Storavatnet og regler for bålbrenning skal følges. Det er ikke tillatt å drikke alkohol i Egget. Utesko skal ikke benyttes inne. Utesko skal plasseres på matte rett innenfor døren. På grunn av allergier er det ikke tillatt å ha med kjæledyr i hytten. Husk å rydde/koste hytten og å ta med deg alt søppel. Vi ber at dere forlater Egget ryddet, ren og klar for neste familie innen kl.12:00. Det er kun mulig å bestille overnattinger for inneværende kalendermåned og to måneder fram i tid. Ny periode blir lagt ut ved overgang til ny kalendermåned, den 1. i hver måned . Det er kun tillatt med to reservasjoner pr husstand pr år. Bymiljøetaten tar forbehold om at bookingene kan endres dersom det oppstår spesielle eller uforutsette situasjoner. Leietaker plikter å lese og følge reglene for Egget som står i informasjonsmappen. Ved bestilling godtar du våre regler og betingelser.','Nøkkelen hentes hos Innbyggerservice i Kaigaten 4. Åpningstider: Mandag: 8:00-15:00 Tirsdag: 8:00-15:00 Onsdag. 8:00-15:00 Torsdag: 8:00-15:00 Fredag: 8:00-15:00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'145',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN - Kafèområde',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Linkens Kaféområde har et utstyrt kjøkken, scene med lyd og lyssystem, sofa og stoler, projektor(hdmi) og lerret, brettspill, trommesett, gitarforsterker og bassforsterker. Dersom man benytter kopper og kar skal disse vaskes etter bruk, Linkens oppvaskmaskin er enkel å betjene. OBS! LINKEN, er forbeholdt aktivitet for barn og unge. I tilfelle hvor barn og unge prioriteres kan øvrige leietagere måtte flytte sin aktivitet i tid og rom. Linkens Kaféområde leies ikke ut til støyende aktiviteter i kontortid da der ikke er tilstrekkelig lyddemping mellom Kaféområde og kontorlandskap. Linken leies ikke ut til private feiringer, som bursdag, jubileum eller religiøse markeringer.','08:00 - 22:00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'753',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Kontrollrom/Lydstudio',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='17'),NULL,NULL,'Tilgjengelig for booking: Ukedag Fra Til Mandag 08:30:00 22:00:00 Tirsdag 08:30:00 22:00:00 Onsdag 08:30:00 22:00:00 Torsdag 08:30:00 22:00:00 Fredag 08:30:00 22:00:00 Lørdag 09:30:00 22:00:00 Søndag 09:30:00 22:00:00 Kontrollrom-Lydstudio Rommet ligger vegg-i-vegg og med vindu til Øvingsrom 5 og er ca. 10 m2. Rommet kan brukes som kontrollrom mot Øvingsrom 5 og Kultursal, eller som et eget digitalt produksjonsrom. Søknader om leie behandles på dagtid i ukedagene. Søknader behandles ikke på kveldstid og i helgene. Lokaler kan ikke benyttes uten godkjent søknad. Følgende bruksbegrensninger gjelder: - Maksimum 3 personer kan være tilstede i studioet samtidig. - Enkeltleie kan ha varighet på maksimum 4 timer pr. søknad. Hvis Kontrollrom/Lydstudio leies kun til opptak, må også Øvingsrom 5 leies med da disse to rommene ikke er lydtette mot hverandre. Kontroller derfor at det er ledig i kalenderen i begge lokaler før søknad sendes. Husk også å leie Øvingsrom 5, dersom du skal bruke dette ved innspilling. Rommet blir utstyrt med opptaksmulighet med 16 linjer inn / ut, multimedia-PC med innspillingsprogram / kreativ programvare, MIDI-keyboard, og mikrofoner.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'157',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='69'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),80,'kilde','Storsal Salen har kjøkken (med begrenset med kjørler), sofakrok, projektor & lerret, mobile speilvegger, dansemaskin og lydanlegg ( mindre bluetooth anlegg/større konsert PA). (For øyeblikket er ikke projektor tilgjengelig, men lerretet er der). Flere bord og stoler/benker er tilgjengelige. Anbefaler uansett alle som skal leie om å se på lokalet før de leier. Ungdommens hus er et rusfritt lokale, og Storsalen leies i all hovedsak ut til åpne kultur- og fritidsaktiviteter. U ngdommer prioriteres. Salen leies IKKE ut til bryllup, konfirmasjon, runde dager og andre større og/eller private feiringer/festligheter . Eneste unntaket er barnebursdager hvis det ikke er plass på skolene (se mer info nederst). Kapasitet: ca.80 (Færre hvis det er bord og stoler, flere hvis man tar bort alt) Barnebursdag: Prøv hos nærmeste skole først, da Ungdommens hus hovedsakelig er for annet bruk. Skolene har egne GRATIS ordninger for barnebursdager. Ungdommens hus kan gjøre unntak for barnebursdager som ikke får plass på skolene, men det inkluderer en kostnad (se leiebetingelser). Ps. Per i dag, har vi ikke nok kjørler og bestikk til slike arrangement, så vi anbefaler å ta med selv (evt engangsbruk). PS. Forvent minst 3 arbeidsdager for svar på søknad - så søk i god tid i forkant. PPS. Viktig at du har med en god og riktig beskrivelse av aktiviteten din når du SØKER om leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'141',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN - Dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'&lt;p&gt;&lt;br&gt;Dansesalen brukes som dansesal, og medieverksted for filmklubben(film/foto).&lt;br&gt;&lt;br&gt; Dansesalen er utstyrt med speilvegg og JBL Boombox.&lt;/p&gt;&lt;p&gt;Har du en aktivitet for barn/ungdom som kan passe her, ta kontakt med &lt;a href=&quot;mailto:Thomas.honningsvag@bergen.kommune.no&quot;&gt;Thomas.honningsvag@bergen.kommune.no&lt;/a&gt;&lt;br&gt;&lt;br&gt;&lt;span&gt;OBS! &lt;/span&gt;&lt;span&gt;LINKEN, er forbeholdt aktivitet for barn og unge.&lt;/span&gt;&lt;span&gt; &lt;/span&gt;&lt;br&gt;&lt;span&gt;I tilfelle hvor barn og unge prioriteres kan øvrige leietagere måtte flytte sin aktivitet i tid og rom.&lt;br&gt;&lt;/span&gt;Linkens dansesal leies ikke ut i kontortid da der ikke er tilstrekkelig lyddemping mellom dansesal og kontorlandskap.&lt;/p&gt;','Ukedager inkl fredag: 17:00-22:00 for aktiviteter som innebærer høy lyd(musikk), eller annet støy. 08:00-17:00 for aktiviteter som ikke er belastende for tilstøtende kontorlandskap. Helg, lør-søn: 08:00-22:00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'139',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='111'),'LINKEN - Designverksted',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='20'),NULL,NULL,'Linken Designverksted 4 til 8 arbeidsplasser + evt. instruktør. Har du en aktivitet for barn/ungdom som kan passe her, ta kontakt med Thomas.honningsvag@bergen.kommune.no Pris: -Ungdom til og med 25 år: kr. gratis -Frivillige/ideelle organisasjoner: kr. 50/time. -Voksne kr. 300/time. -Kommersielle aktører kr. 300/time. OBS! LINKEN, er forbeholdt aktivitet for barn og unge. Barn under 13 år skal ikke benytte Desigernverksted uten tilsyn fra voksne. Designerverksted leies ikke ut til andre aktiviteter enn kunst og hånd verk. I tilfelle hvor barn og unge prioriteres kan øvrige leietagere måtte flytte sin aktivitet i tid og rom.','07:00-22:00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'91',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='5'),'Storsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Dekkeplass til ca 60 personer Demping på lysene Lerret og prosjektor Piano Tilhørende kjøkken: Servise til ca 60 personer Kjøleskap. Oppvaskemaskin (steamer) Komfyr, kaffetrakter og vannkoker Serveringsbord på hjul Prioriterte utleieformål er kulturarrangementer og andre arrangementer/aktiviteter i regi av frivillige lag/organisasjoner, f.eks konserter, forestillinger, strøksmarkeringer, seminarhelger, etc. Salen leies også ut til kurs/konferanser , og enkelte privatarrangementer; privatarrangementer på dagtid , barnebursdag, dåp/navnefest, minnestund, konfirmasjon, bryllup. Andre privatarrangementer på kveldstid (f.eks «runde dager») leies det ikke ut til. Det leies heller ikke ut til firmafester el.l. Prisliste finner du under "Dokumenter" lenger nede på siden. Praktisk informasjon ved utleie (utdrag fra ordensregler): -Et vilkår for leie er at leietaker setter seg godt inn i ordensregler og branninstruks (juridiske vilkår i søknadskjema). -Kulturlokalene er først og fremst aktivitetslokaler beregnet til kulturaktivitet for barn og unge og frivillige lag/organisasjoner. -Kulturhusene er ubetjente, dette medfører at leietakere må rigge og rydde selv. Søppel skal av leietaker kastes i egen container utenfor huset. -Kjøkkenet er ikke et produksjonskjøkken, det er et kjøkken primært for lag og organisasjoner. Det er ikke oppvaskmaskin, men steamer. -Lokalene (ressursene) brukes av flere organisasjoner daglig. -Alle gjenstander/eiendeler blir satt igjen på leietakers egen risiko. -Renhold utføres en gang pr dag, mandag til og med fredag. Det blir ikke utført renhold lørdag og søndag. -2. etg har kun ett toalett (som også er tilrettelagt for rullestolbrukere). -Nøkler til lokalene må hentes på Bergenhus og Årstad kulturkontor, Kong Oscarsgate 54, 1-3 dager før leiedato, og leveres inn igjen første hverdag etter leiedato. -Ved leie kveldstid kreves det at leietaker tar hensyn til naboer og nærmiljø når det gjelder lydnivå/støy. Det settes begrensninger for slutt-tid for arrangementene (stilletid gjelder fra kl 23.00 man-tor+søn, og fra kl 00.00 fre og lør). Ved enkelte arrangementer kan det bli satt ytterligere tidsbegrensninger, f.eks ved store (folkerike) arrangementer. Se ellers ordensregler.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'5',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='3'),'Rom 2 - kultur',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Aktivitetsrom / møterom for mindre grupper',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'6',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='3'),'Rom 3 - kultur',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Aktivitetsrom / møterom for mindre grupper',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
