INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'86',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='133'),'Kanoer',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Bymiljøetaten og Fløibanen AS har 9 kanoer til utlån for skoleklasser, lag og organisasjoner. Ønsker du å låne kanoene sender du søknad via Aktiv Kommune til Bymiljøetaten. Lån av kanoene er gratis dersom vilkårene overholdes. I perioden 20.juni til 16.august 2026 driftes utlån av kanoene av Fløyen AS, og det er ikke anledning til ordinær booking i denne perioden. Sesongen varer fra påske til høstferien. Kanoene lånes ikke ut til privatpersoner. Nøkkelen hentes og leveres tilbake hos Bymiljøetaten i Johannes Bruns gate 12. Åpningstidene er mandag til fredag fra 08:00 til 14:00. Låntaker henter nøkkelen så tett opptil arrangementet som mulig, og leverer den tilbake så fort som mulig etter at låneperioden er over. Dersom vi ikke får tilbake nøkkelen vil vi sende ut en faktura på kr. 500,- til ansvarlig låntaker. Mangler ved lånt utstyr skal innrapporteres ved innlevering av nøkler. Låntaker er ansvarlig for bruk av kanoene og skal alltid ha oppsyn med bruken. Bruk av redningsvest/flytevest er påbudt. Ansvarlig må være fylt 18 år og ha godkjent praktisk livredningsprøve (HLR). Låntaker må ha med eget førstehjelpsutstyr. Låntaker plikter å lese gjennom og akseptere vilkår for bruk av kanoene, se Dokumenter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
