INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'819',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Klasserom 3001 (UKEDAGER FRA KL. 16.00)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Stort klasserom (Rom 3001 - Klasserom, stort), 75 m2, ved voksenopplæringen. Rommet er møblert med pulter og stoler som må settes tilbake dersom de blir flyttet på. 3. etasje. Tilgjengelig for booking: Mandag 16:00:00 22:00:00 Tirsdag 16:00:00 22:00:00 Onsdag 16:00:00 22:00:00 Torsdag 16:00:00 22:00:00 Fredag 16:00:00 22:00:00 Lørdag 10:00:00 22:00:00 Søndag 10:00:00 22:00:00',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'924',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Auditorium 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='40'),NULL,NULL,'Auditorium 2 er utstyrt med: Sitteplasser (76 seter) 2 smartskjermer, mikrofoner og lydutstyr Tilrettelagt for rullestolbrukere fremst i rommet Størrelse: 69 m²','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'918',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Gymsal 2 - Ballsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Idrettssal for ballsport er utstyrt med: Mikrofon Lydanlegg via blåtann Innebygde høgtalere, USB-C-tilkopling Basketballstativer Håndballmål Volleyballstenger og nett Blinker og fangnett til bueskyting Benker Bruk av idrettssalen Idrettssalen brukes til idrettsaktiviteter og passer best for ballsport med mindre grupper. Mandag til fredag (ettermiddag og kveld): Salen brukes av idrettslag som har fått faste treningstider. Lørdag og søndag: Grupper på opptil 20 personer kan reservere salen. Du kan reservere inntil 2 timer per dag. Tilgjengelig utstyr i helgen: Fotballer Basketballer Volleyballer Håndballer Innebandyutstyr Badmintonracketter (merk: det finnes ikke stativ til badminton) Du kan ta med eget småutstyr hvis du trenger det til din aktivitet. Lagring av utstyr: Bare idrettslag med faste treningstider kan lagre utstyr, og det må avtales med Etat for idrett.','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays : 08.00-21.00 Saturday and Sunday : 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
