INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'1050',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='136'),'Varden Møterom 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'981',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Drop-in - Gymsal 2 ballsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Idrettssal for ballsport er utstyrt med: Mikrofon Lydanlegg via blåtann Innebygde høgtalere, USB-C-tilkopling Basketballstativer Håndballmål Volleyballstenger og nett Blinker og fangnett til bueskyting Benker Bruk av idrettssalen Idrettssalen brukes til idrettsaktiviteter og passer best for ballsport med mindre grupper. Mandag til fredag (ettermiddag og kveld): Salen brukes av idrettslag som har fått faste treningstider. Lørdag og søndag: Grupper på opptil 20 personer kan reservere salen. Du kan reservere inntil 2 timer per dag. Tilgjengelig utstyr i helgen: Fotballer Basketballer Volleyballer Håndballer Innebandyutstyr Badmintonracketter (merk: det finnes ikke stativ til badminton) Du kan ta med eget småutstyr hvis du trenger det til din aktivitet. Lagring av utstyr: Bare idrettslag med faste treningstider kan lagre utstyr, og det må avtales med Etat for idrett.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'801',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='150'),'Dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Dansesalen er en sal med dansegulv, musikkanlegg og speilvegg. Gulvarealet er 49 m2. Salen passer godt for både dans, yoga, trim og lignende aktiviteter. Det er musikkanlegg tilgjengelig med blåtann oppkobling. Ta kontakt med personalet på Fysak for lån av nøkkel til dansesal. Salen må låses og nøkkel leveres tilbake. På grunn av spesialgulv må det ikke brukes sko med harde såler eller sko som setter merker i gulvet. Det er ikke tillat med mat og drikke i Dansesal.','Booking dansesal ukedager: 14.00 - 21.45 Booking dansesal helger: 14.00 - 18.45',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'980',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Drop-in - Gymsal 3 dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Denne idrettssalen har speil og er utstyrt med: Mikrofon Lydanlegg med blåtann Innebygde høyttalere med USB-C-tilkobling Speil Bordtennisbord Turnmatter Tjukkas Hva slags aktiviteter passer i salen? Salen brukes til idrettsaktiviteter som ikke skader speil på veggen . Ballsport er derfor ikke tillatt. Eksempler på passende aktiviteter: Dans Bordtennis Badminton Styrketrening Aerobic og Yoga Andre «rolige» aktiviteter Mandag til fredag (ettermiddag og kveld): Salen brukes av idrettslag med faste treningstider. Lørdag og søndag: Grupper på opptil 20 personer kan reservere salen. Du kan reservere inntil 2 timer per dag. Tilgjengelig utstyr i helgen: Vegg med speil Bordtennisbord og racketer Turnmatter Hoppemadrass Badmintonracketer (merk: det finnes ikke stativ til badminton) Du kan ta med eget småutstyr dersom du trenger det til din aktivitet. Lagring av utstyr: Bare idrettslag med faste treningstider kan lagre utstyr, og det må avtales med Etat for idrett.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='26' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:bergen' AND r.ekstern_id='139' ON CONFLICT DO NOTHING;
